class SensorItem(BaseModelWithHash):
    model_config = ConfigDict(extra="forbid")
    oem: str | None = Field(
        None,
        description="The measurement sensor manufacturer.",
        examples=["Vector", "NRG Systems", "Thies"],
        title="Sensor OEM",
    )
    model: str | None = Field(
        None,
        description="The measurement sensor model.",
        examples=["#200P", "First Class Advanced", "A100L2"],
        title="Sensor Model",
    )
    serial_number: str | None = Field(
        None,
        description="The serial number of the sensor installed.",
        title="Serial Number",
    )
    sensor_type_id: SensorTypeId | None = Field(
        None,
        description="The measurement sensor type e.g. anemometer.",
        title="Sensor Type",
    )
    classification: str | None = Field(
        None,
        description="The classification of a particular anemometer for this location. This combines the class index "
        "(number) with the terrain class (A, B, C, D or S) e.g. 1.2A. The format of this is validated by "
        "a regex which has the form of ^[0-9][.][0-9][ABCDS]$ i.e. digit.digit followed by a character.",
        examples=["1.0A", "3.2B", "2.7S", "10.32S"],
        title="Classification",
    )
    instrument_poi_height_mm: float | None = Field(
        None,
        description="This is the physical height dimension, in mm, of the sensor's point of interest, i.e. point of "
        "measurement. This is to aid IEC mounting calculations. It is not the height above ground level at "
        "which it is deployed. For example, if the sensor is an anemometer it is the height from the "
        "bottom of the instrument to the centre of the cups. For a sonic anemometer it is the centre of "
        "the sampling volume. For a horizontal propeller anemometer it is the axis of rotation of the "
        "propellers. For a wind vane it is the top of the vane.",
        examples=[
            "169 mm for a Vector A100 anemometer "
            "(https://www.windspeed.co.uk/ws/index.php?option=displaypage&op=page&Itemid=48#dimensions)."
        ],
        title="Instrument Point of Interest Height [mm]",
    )
    is_heated: bool | None = Field(
        None,
        description="Is the sensor heated to reduce the effect of icing. This is usually relevant for wind speed and "
        "wind vane sensors. True is for when the sensor is heated and false is for when the sensor is "
        "not heated.",
        examples=[
            "true (if the sensor is heated)",
            "false (if the sensor is not heated)",
        ],
        title="Is Heated",
    )
    sensor_body_size_mm: float | None = Field(
        None,
        description="This is the instrument body size in mm. This parameter is used in IEC 61400-12-2 to ensure that "
        "the size of the anemometer body is smaller than the diameter of the tube used to mount the "
        "anemometer.",
        examples=["50"],
        title="Sensor Body Size [mm]",
    )
    date_from: DateFrom
    date_to: DateTo | None
    notes: Notes | None = None
    update_at: UpdateAt | None = None
    calibration: set[CalibrationItem] | None = Field(
        None,
        description="The sensor calibration details. This is typically expected for anemometers, but not necessarily "
        "required for other sensor types.",
        title="Calibration",
    )

    @field_validator("classification")
    def validate_classification(cls, value):  # noqa: N805
        pattern = re.compile(r"^[0-9]\.[0-9][ABCDS]$")
        if value and not pattern.match(value):
            raise ValueError("Invalid classification format")
        return value


