class IeaWindResourceAssessmentDataModel(BaseModel):
    model_config = ConfigDict(extra="allow")
    author: str = Field(
        ...,
        description="The person or system who created this data model representing a specific mast.",
        examples=["Stephen Holleran", "Joe Bloggs"],
        title="Author",
    )
    organisation: str = Field(
        ...,
        description="The organisation the Author is from.",
        examples=["brightwind", "Wind Developer Ltd."],
        title="Organisation",
    )
    date_created: date = Field(
        ...,
        description="The date this file was created. Format should be YYYY-MM-DD",
        examples=["2020-07-28"],
        title="Date",
        alias="date",
    )
    version: str = Field(
        ...,
        description="The version of the IEA WRA Data Model this file is based on. The format of this follows Semantic "
        "Versioning with the year and month tagged on after. E.g. 1.1.1-2020.07",
        examples=["0.1.0-2020.06", "1.1.1-2020.07"],
        title="Version",
    )
    license: str | None = Field(
        None,
        description="Expected to be used as the Dublin Core Metadata Initiative intended. "
        "Link: http://purl.org/dc/terms/license Definition: A legal document giving official permission "
        "to do something with the resource. Comment: Recommended practice is to identify the license "
        "document with a URI. If this is not possible or feasible, a literal value that identifies the "
        "license may be provided.",
        examples=["https://opensource.org/license/bsd-3-clause/", "BSD-3-Clause"],
        title="License",
    )
    plant_name: str | None = Field(
        None,
        description="The name of the wind farm this met mast is associated with.",
        examples=["A Name of Wind Farm"],
        title="Plant Name",
    )
    plant_type: PlantType | None = Field(
        None,
        description="The type of renewable generation plant it is.",
        title="Plant Type",
    )
    measurement_location: set[MeasurementLocationItem] = Field(
        ...,
        description="This is the geographic location of the meteorological measurement station i.e. a met mast/tower "
        "or remote sensing device.",
        title="Measurement Location",
    )

    @field_validator("version")
    def validate_classification(cls, value):  # noqa: N805
        pattern = re.compile(r"^([0-9]{1,2})[.]([0-9]{1,2})[.]([0-9]{1,2})-([0-9]{4})[.]([0-9]{2})$")
        if value and not pattern.match(value):
            raise ValueError("Invalid version format")
        return value
